import{_ as s,o as d,c as e,a3 as a}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"迟滞输出现象(4n物品卡半格)整理与原理探究","description":"","frontmatter":{"translationSource":{"title":"迟滞输出现象(4n物品卡半格)整理与原理探究","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=tZlUFONP0H56rrjqpWpAn9","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/output-lag-observations-and-mechanism-investigation"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/output-lag-observations-and-mechanism-investigation"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/output-lag-observations-and-mechanism-investigation"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/output-lag-observations-and-mechanism-investigation"}]]},"headers":[],"relativePath":"zh/output-lag-observations-and-mechanism-investigation.md","filePath":"zh/page-tZlUFONP0H56rrjqpWpAn9.md"}'),i={name:"zh/output-lag-observations-and-mechanism-investigation.md"};function r(c,t,l,n,o,b){return d(),e("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="迟滞输出现象-4n物品卡半格-整理与原理探究" aria-hidden="true"></span><span class="logistics-source-anchor" id="output-lag-4n-items-stall-for-half-a-tile-observations-and-mechanism-investigation" aria-hidden="true"></span><h1 id="迟滞输出现象-4n物品卡半格-整理与原理探究" tabindex="-1">迟滞输出现象(4n物品卡半格)整理与原理探究 <a class="header-anchor" href="#迟滞输出现象-4n物品卡半格-整理与原理探究" aria-label="Permalink to &quot;迟滞输出现象\\(4n物品卡半格\\)整理与原理探究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>tZlUFONP0H56rrjqpWpAn9</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=tZlUFONP0H56rrjqpWpAn9" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><table tabindex="0"><thead><tr><th>标题</th><th>详情</th><th>单选</th><th>日期</th><th>图片</th></tr></thead><tbody><tr><td>发现了现象</td><td>@晨隐_ 实验减法时正式提出该问题</td><td>相关实验</td><td></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-8395db0bd51e3909.q90-4afcb829f8cf2c22.webp" alt="C$XI5D1D68S@~ZS1CBDpng"></td></tr><tr><td>触发条件推测</td><td></td><td>相关推测</td><td></td><td></td></tr><tr><td>首个可复现实验</td><td>@天云-翱翔天际 发现了一种可复现可空的该现象触发方法，该方式需要存储箱填满且分流器通向物流器后最后通向工厂的传送带比通向填满的箱子的传送带后放，此时比例与分流器到物流器的距离正相关，暂时无法断定多个分流器时按哪一个距离计算</td><td>相关实验</td><td></td><td></td></tr><tr><td>触发原理推测</td><td></td><td>相关推测</td><td></td><td></td></tr><tr><td>新的一批实验结果-1</td><td>@jnk1698 完成了新的神秘实验，具体见下文折叠部分</td><td>相关实验</td><td></td><td></td></tr><tr><td>关于水管存在的相似问题</td><td>@jnk1698 进行了关于水管摆出相似的结构下也存在的异常问题</td><td>相关实验</td><td></td><td></td></tr></tbody></table><details><summary>实验-1</summary><blockquote><p>需要连接右侧箱子的输入口的传送带最后放置</p><p>上面路线的物流器+传送带可以改成传送带+物流器或物流器+物流器，但是不能只用一段传送带或一个物流器，也不能换成传送带+物流器+传送带，也不能换成物流器+传送带+物流器，？</p><p>右边的箱子也是可有可无的</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-49770de69f8fa907.q90-e3406bb657beadd3.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-b9152f887663e1b0.q90-9c77e869e76bf7b3.webp" alt="图片"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-221f41b3bdd2a879.q90-a111f3b94b6963dd.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9f6f27ee0a08498a.q90-69e39f6f36eb4b7b.webp" alt="图片"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-814c2784e0c65ed2.q90-c77e8aa17ec93195.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-084772e32fbb42b7.q90-df98765d05c3d7ab.webp" alt="图片"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-c4d320d51e7df9d4.q90-10f3d3451db10cd4.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-c71f8dd9385511a4.q90-fc174ec704bb600f.webp" alt="图片"></td></tr></tbody></table></details><details><summary>水管版本实验</summary><p>使用以下结构查看结果</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-40c0238d9a7acd64.q90-6639e3e07f4dc54a.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p><p>先让水循环起来，然后接入优先级更高的锦草溶液，锦草溶液经过会导致迟滞输出的结构</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-16d181bcdeb5cae3.q90-bc2f17055347637f.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-64d9129f1bceaf9f.q90-3ef6dcc129bff8cd.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p><p>液体的现象与传送带略有不同，为2n卡1格，n为分流器到下一个物流器的距离，小于1时当1</p></details><details><summary>对4n卡1s物品序列进行低优先插入的实验</summary><p>使用实验-1产出的物品序列，对其进行优先汇入，汇入另一支低优先的物品，结果为物品序列中的n+1个物品后汇入一个另一支物品。这里的n不再将0视为1</p></details><details><summary>实验-2</summary><p>@恒星泰斗 与@c 在测试 顺环 结构（见阻尼理论的bugs栏目）时出现了疑似4n卡1s的结果，具体为出现顺环结构1、直带2、直带3之间轮询为1312循环，在@恒星泰斗 在后来的测试中确认了触发方式，如图，汇流器最后放置</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a7843e55dbc29283.q90-e4f816051f1caa48.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p><p>@jnk 认为准入口是无关的，即得出</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fd40383fcc005226.q90-2d2c8212152ecc30.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p></details><details><summary>位置为浮点数相关推测与实验</summary><p>@Fatal Error A1012 进行了一个实验，如图所示，此时箱子出口的汇流器可能导致了4n卡2s？</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1d008357d9f1f9d5.q90-628c17a431b90ceb.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cfb588dede9a5847.q90-35a2aa61b25841b1.webp" alt="迟滞输出现象4n物品卡半格整理与原理探究"></p><p>显然的，图二物品并非间隔1格，经排查与尝试复现，得出结论是收取传送带上的一个物品后，其他物品会渲染为真实位置，以下是相关测试图片</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-8e7d3ac3b6e624d0.q90-e0752050a2c7bffb.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-0d861dc6f16ec3bd.q90-e27c11f007e73e0b.webp" alt="图片"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-de72f92436ef814a.q90-326aaf06452867a4.webp" alt="图片"></td><td></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-81d56e5da746fe42.q90-0721dcd78d7d6d36.webp" alt="图片"></td><td></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-06fe53272bf33b19.q90-ed04a4b7c8af3dd1.webp" alt="图片"></td><td></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-484b29cc5598323a.q90-967996c2261cc2f9.webp" alt="图片"></td><td></td></tr></tbody></table></details><p>根据目前的实验结果，推测物品位置应当是小数，而不是被限制为两种情况，且从传送带上收取一个物品可以显示真实的物品分布，该物品分布经过一个物流器后再次被对齐为两种情况，依旧不知道触发条件，认为某些情况的轮询可能由此引发。</p><details><summary>聊天记录-对当前研究的总结</summary><p>jnk 2026/5/23 14:54:02</p><p>jnk</p><p>4n卡1s的现象目前是不是可以分为两类，目前还没有找到其他的触发方式或确定其他触发方式引发的是该问题</p><p>一类是汇流器紧贴箱子出口时的顺环导致的现象</p><p>另一类是分流器一侧无法输出导致的现象，第二类又可以分为断尾侧无法输出和非断尾侧无法输出两个子类</p><p>目前触发的情况来看，汇流器顺环类只会出现4物品卡1s；分流器类则与最终通路的分流器连接的物流元件长度有关，且该物流元件之后必须要有其他物流元件；分流器一侧断尾类的触发要求断尾方向的物流元件总数为2，且只要有一个符合条件的断尾侧即可；分流器一侧非断尾类的；对于分流器类，我们目前不知道阻塞是否是其中的必要要求</p><p>以上均为经验性总结，可能随着实验成果而改变</p></details><p>@c 对实验一进行了扩展，其下游通路有多出口时，必须全部断开重新放置</p><details><summary>聊天记录-使动-转移-移动逻辑</summary><p>jnk 2026/8/13 8:13:36</p><p>使动-转移-移动逻辑：<br> 物品只会移动/转移一次。<br> 物流元件运算时会先使下游元件内部物品移动，再检查自身内部抵达终点的物品是否可以转移到下一个元件，最后移动自身内部物品。<br> 分流器在使动阶段，如果使动的对象是汇流器，可能导致汇流器进行转移，与汇流器连接下游和连接上游分流器的顺序有关。</p><p>假定两个元件中上游先计算：<br> x;x,x#x表示无物品，7～0表示刚进入的物品～即将输出的物品，左侧为上游<br> 7;x,x...#...表示跳过容易理解的时间<br> 1;x,x<br> :0;x,x#移动，使用:表示同一tick内的行为<br> :0;x,x#使动<br> :0;x,x#转移，但是物品刚经过移动，无法进行转移<br> 0:x,x<br> 7;7,x...<br> 0;0,x<br> :0;x,7#使动<br> :x;7,7#转移<br> :x;7,7<br> :x;7,7#下游的使动-转移-移动没有任何变化，其内部两个物品都移动/转移过<br> 7;7,7...#自0;0,x后转移了一个物品<br> 0;0,0<br> :0;0,0...#移动，这里跳过上游元件的使动-转移-移动和下游元件的使动，都没有变<br> :0;0,x#下游元件转移<br> :0;x,7#下游元件移动<br> 0;x,7#出现卡1tick<br> :0;x,6<br> :x;7,6<br> :x;7,6<br> 7;7,6...#自0;0,x后转移两个物品<br> 1;1,0<br> :1;0,0#使动<br> :1;0,0#转移<br> :0;0,0#移动<br> :0;0,0#下游使动<br> :0;0,x#下游转移<br> :0;0,x#下游移动<br> 0;0,x#自上一次0;0,x后一共转移两个物品，发生一次卡顿，为4*2卡1s（4tick=1s），容易理解下游元件的长度决定4n卡1s中的n</p></details><p>关于顺环的进一步研究，我们需要研究如图示没有下游输出的环</p><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f9ad0ee9a15d21c5.q90-9c61717ccb8fe1e6.webp" alt="图片"></td></tr></tbody></table></div>',1)])])}const g=s(i,[["render",r]]);export{m as __pageData,g as default};
